mapper.select:
SELECT a.resource_id, a.name, b.name directionName, a.difficulty, a.logo, a.public isPublic, COUNT(c.duration) lessonCount, if(SUM(c.duration) IS NULL, 0, SUM(c.duration)) courseDuration FROM oj_course a LEFT JOIN oj_course_category b ON a.category_id = b.resource_id LEFT JOIN oj_course_lesson c ON a.resource_id = c.course_id WHERE a.resource_id in
#{courseId}
GROUP BY a.resource_id
